288			Anchor: 10,
289			Target: CorrectionTarget{X: 0, Y: 0, Heading: targetHeading, Variance: 0},
290		})
291		if err != nil {
292			t.Fatalf("Correct: %v", err)
293		}
294		dHeading := normalizeAngle(normalizeAngle(targetHeading) - anchorHeading)
295		want := normalizeAngle(anchorHeading + dHeading)
296		if want >= 0 {
297			t.Fatalf("test setup: expected wrap to the -pi side, got %v", want)
298		}
299		if rec.Poses[0].After.Heading != want {
300			t.Fatalf("corrected heading = %v, want boundary-folded %v", rec.Poses[0].After.Heading, want)
301		}
302		if rec.Poses[0].After.X != 0 || rec.Poses[0].After.Y != 0 {
303			t.Fatalf("anchor position changed: (%v,%v)", rec.Poses[0].After.X, rec.Poses[0].After.Y)
304		}
305		// 正 π 始终表示为负 π。
306		if h := rec.Poses[0].After.Heading; h >= math.Pi || h < -math.Pi {
307			t.Fatalf("heading %v outside [-pi, pi)", h)
308		}
309	}
