884					}
885					got[key] = struct{}{}
886				}
887				for key := range want {
888					if _, ok := got[key]; !ok {
889						return fmt.Errorf("%w: correction %s misses landmark %s occurrence %d observed in its range", ErrCorrupt, cr.ID, key.id, key.num)
890					}
891				}
892				for key := range got {
893					if _, ok := want[key]; !ok {
894						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d with no observation in its range", ErrCorrupt, cr.ID, key.id, key.num)
895					}
896				}
