946		// 结果仍以最后一次覆盖记录为准；同一文件内其他依据完整的衔接仍须检
947		// 查。校正记录保持提交时的快照与次序，不为消除矛盾而改写。
948		prevByFrame := make([]int, len(fd.Trajectory))
949		for j := range prevByFrame {
