960					got := cr.Poses[j-r.anchorIdx].Before
961					t := fd.Trajectory[j].Time
962					if !coordClose(got.X, want.X) {
963						return fmt.Errorf("%w: correction %s records pre-correction x %v at frame time %d but the previous correction %s covering that frame recorded corrected x %v", ErrCorrupt, cr.ID, got.X, t, prev.ID, want.X)
964					}
965					if !coordClose(got.Y, want.Y) {
966						return fmt.Errorf("%w: correction %s records pre-correction y %v at frame time %d but the previous correction %s covering that frame recorded corrected y %v", ErrCorrupt, cr.ID, got.Y, t, prev.ID, want.Y)
967					}
968					if !angleClose(got.Heading, want.Heading) {
969						return fmt.Errorf("%w: correction %s records pre-correction heading %v at frame time %d but the previous correction %s covering that frame recorded corrected heading %v", ErrCorrupt, cr.ID, got.Heading, t, prev.ID, want.Heading)
970					}
971					if got.Variance != want.Variance {
972						return fmt.Errorf("%w: correction %s records pre-correction variance %v at frame time %d but the previous correction %s covering that frame recorded corrected variance %v", ErrCorrupt, cr.ID, got.Variance, t, prev.ID, want.Variance)
973					}
974				}
975				// 不论是否比较，本记录都成为该帧新的最后一次覆盖记录。
976				prevByFrame[j] = i
977			}
978		}
979		// 当前保存轨迹与“作用于该帧的最后一次校正”一致性核对：上面的几何
980		// 核对只确认每条记录自身保存的前后值描述同一次刚体重定位，不确认
981		// 当前轨迹中的保存位姿就是按提交次序最后一条覆盖该帧的记录的校正
982		// 后结果——两条记录各自合法、校验和正确，但当前轨迹可能与最后一次
983		// 校正的结果矛盾（例如覆盖 100~300 的第一条校正后追加 400 帧，第二
984		// 条覆盖 200~400，则当前 100 对应第一条、200/300/400 对应第二条；
985		// 后来追加的 500 帧不属于任一条，旧记录也不因后续校正而被改写）。
986		// 对每个已导入帧 j（trajectory[0] 是初始位姿，不是可校正的帧），先
987		// 按提交次序求最后一条覆盖它的记录（不论依据是否完整）：若该记录
988		// 范围内逐帧依据完整，就把其该帧的校正后值作为期望，逐帧核对保存
989		// 的位置、朝向与位置方差，锚点与结束帧同样在内；范围内没有任何路
