991		// 盾）。兼容规则：最后一条覆盖记录范围内含缺少逐帧依据的 null 旧
992		// 帧时跳过该帧的比较，而不是回退到更早的完整依据记录要求当前位姿
993		// 回到旧结果；其前后帧若最后覆盖记录不同且该记录依据完整，仍须核
994		// 对；没有任何覆盖记录的帧不核对，纯旧文件因此全部自然跳过。位置
995		// 用 coordClose、朝向用 angleClose（均为 1e-9 相对/绝对容差，处理
996		// ±π 跨边界），方差必须完全一致；合并距离只是导入/校正时的观测接
997		// 纳门槛，不能用来放宽这些要求。
998		lastByFrame := make([]int, len(fd.Trajectory))
999		for j := range lastByFrame {
1000			lastByFrame[j] = -1
1001		}
1002		for i := range fd.Corrections {
1003			r := corrRanges[i]
1004			for j := r.anchorIdx; j <= r.endIdx; j++ {
1005				lastByFrame[j] = i
1006			}
1007		}
1008		for j := 1; j < len(fd.Trajectory); j++ {
1009			i := lastByFrame[j]
1010			if i < 0 || !corrRanges[i].fullyBased {
1011				// 没有任何覆盖记录，或最后一条覆盖该帧的记录范围内含缺少
1012				// 逐帧依据的 null 旧帧：按兼容规则跳过，不改用更早记录。
