1019			if !finitePose(got) {
1020				return fmt.Errorf("%w: frame at time %d contradicts its last correction %s: saved pose is non-finite", ErrCorrupt, got.Time, cr.ID)
1021			}
1022			if !coordClose(got.X, want.X) {
1023				return fmt.Errorf("%w: correction %s is the last correction covering frame time %d but saved x %v does not match its corrected x %v", ErrCorrupt, cr.ID, got.Time, got.X, want.X)
1024			}
1025			if !coordClose(got.Y, want.Y) {
1026				return fmt.Errorf("%w: correction %s is the last correction covering frame time %d but saved y %v does not match its corrected y %v", ErrCorrupt, cr.ID, got.Time, got.Y, want.Y)
1027			}
