cd /tmp && mkdir -p hdcheck && cd hdcheck && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"math"
)

func normalizeAngle(a float64) float64 {
	if a == 0 {
		return 0
	}
	if -math.Pi <= a && a < math.Pi {
		return a
	}
	a = math.Mod(a+math.Pi, 2*math.Pi)
	if a < 0 {
		a += 2 * math.Pi
	}
	a -= math.Pi
	if a >= math.Pi {
		a -= 2 * math.Pi
	}
	return a
}

func main() {
	// Bug scenario: anchor heading 1, target 1e-20
	anchor := 1.0
	tgt := 1e-20
	d := normalizeAngle(tgt - anchor)
	fmt.Printf("dHeading=%v (exact -1? %v)\n", d, d == -1)
	fmt.Printf("anchor corrected via apply: %v (want %v)\n", normalizeAngle(anchor+d), tgt)

	// Across-pi test: does normalizeAngle(t) == normalizeAngle(a + normalizeAngle(normalizeAngle(t)-a))?
	a := normalizeAngle(math.Pi - 1e-15)
	t := a + 3e-15
	nt := normalizeAngle(t)
	dh := normalizeAngle(nt - a)
	want := normalizeAngle(a + dh)
	fmt.Printf("across-pi: nt=%v want=%v equal=%v\n", nt, want, nt == want)

	// also check for a range of anchor headings / tiny targets
	mismatch := 0
	for _, ah := range []float64{0.5, 1, 2, 3, -1, -2.5, math.Pi - 1e-15, -math.Pi + 1e-14, 1e-16} {
		for _, tg := range []float64{1e-20, -1e-20, 1e-16, -1e-16, 0.3, -2.9} {
			nt := normalizeAngle(tg)
			dh := normalizeAngle(nt - ah)
			got := normalizeAngle(ah + dh)
			if got != nt {
				mismatch++
				fmt.Printf("  mismatch anchor=%v target=%v: nt=%v got=%v\n", ah, tg, nt, got)
			}
		}
	}
	fmt.Println("mismatches:", mismatch)
}
EOF
go run main.go

